package br.com.sussmartcare.notification.domain; import jakarta.persistence.*; import java.time.*; import java.util.*; @Entity @Table(name="notifications") public class Notification { @Id private UUID id; @Column(nullable=false) private UUID patientId; private UUID visitId; @Column(nullable=false) private String type; @Column(nullable=false) private String channel; @Column(nullable=false,length=1000) private String message; @Column(nullable=false) private String status; @Column(nullable=false) private Instant createdAt; private Instant deliveredAt; protected Notification(){} public Notification(UUID patient,UUID visit,String type,String channel,String message){id=UUID.randomUUID();patientId=patient;visitId=visit;this.type=type;this.channel=channel;this.message=message;status="PENDING";createdAt=Instant.now();} public void delivered(){status="DELIVERED";deliveredAt=Instant.now();} public UUID getId(){return id;} public UUID getPatientId(){return patientId;} public UUID getVisitId(){return visitId;} public String getType(){return type;} public String getChannel(){return channel;} public String getMessage(){return message;} public String getStatus(){return status;} public Instant getCreatedAt(){return createdAt;} public Instant getDeliveredAt(){return deliveredAt;} }